using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class BufferedPointCallerProof {
 class Memory:IHorizontalRasterMemory {
  public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public void Load(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++){int p=(seg<<4)+i;byte old;if(Bytes.TryGetValue(p,out old)&&old!=b[i])throw new Exception("Physical alias mismatch");Bytes[p]=b[i];}}
  public ushort ReadWord(ushort s,ushort o){byte a,b;if(!Bytes.TryGetValue((s<<4)+o,out a)||!Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b))throw new Exception("Uncaptured word read");return (ushort)(a|b<<8);}
  public void WriteWord(ushort s,ushort o,ushort v){int p=(s<<4)+o,q=(s<<4)+(ushort)(o+1);if(!Bytes.ContainsKey(p)||!Bytes.ContainsKey(q))throw new Exception("Uncaptured word write");Bytes[p]=(byte)v;Bytes[q]=(byte)(v>>8);}
  public void OrByte(ushort s,ushort o,byte b){throw new Exception("Video effect");}
  public void Compare(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++)if(Bytes[(seg<<4)+i]!=b[i])throw new Exception("Segment "+seg.ToString("X4")+" byte "+i.ToString("X4"));}
 }
 class Fpu:IBufferedPointFpuEffects {
  public ushort CW;public uint Bits;public int Loads,Pops,Waits;public List<string> Effects=new List<string>();
  public void Wait(){Waits++;Effects.Add("WAIT");}
  public void LoadBinary32(IHorizontalRasterMemory m,ushort s,ushort o){Bits=(uint)m.ReadWord(s,o)|((uint)m.ReadWord(s,(ushort)(o+2))<<16);Loads++;Effects.Add("LOAD32");}
  public void StoreControlWord(IHorizontalRasterMemory m,ushort s,ushort o){m.WriteWord(s,o,CW);Effects.Add("STORE_CW");}
  public void LoadControlWord(IHorizontalRasterMemory m,ushort s,ushort o){CW=m.ReadWord(s,o);Effects.Add("LOAD_CW");}
  public void StoreInteger64AndPop(IHorizontalRasterMemory m,ushort s,ushort o){if((CW&0xc00)!=0xc00)throw new Exception("Unverified FPU rounding");long n;if(!FiniteBinary32Integer64.TryConvert(Bits,out n))throw new Exception("Outside finite projection");for(int i=0;i<4;i++)m.WriteWord(s,(ushort)(o+i*2),(ushort)(unchecked((ulong)n)>>(16*i)));Pops++;Effects.Add("STORE_I64_POP");}
 }
 static ushort H(string s){return Convert.ToUInt16(s,16);}static SignedDivide16State Parse(string[] a,int i){return new SignedDivide16State{AX=H(a[i]),BX=H(a[i+1]),CX=H(a[i+2]),DX=H(a[i+3]),SI=H(a[i+4]),DI=H(a[i+5]),BP=H(a[i+6]),CS=H(a[i+7]),IP=H(a[i+8]),DS=H(a[i+9]),ES=H(a[i+10]),SS=H(a[i+11]),SP=H(a[i+12]),EFlags=Convert.ToUInt32(a[i+13],16)};}
 static string Show(SignedDivide16State s){return s.AX+":"+s.BX+":"+s.CX+":"+s.DX+":"+s.SI+":"+s.DI+":"+s.BP+":"+s.CS+":"+s.IP+":"+s.DS+":"+s.ES+":"+s.SS+":"+s.SP+":"+s.EFlags;}
 static int Main(string[] a){try{string prefix=Path.Combine(a[0],"case-"+a[1]);ushort first=H(a[2]),second=H(a[3]),cw=H(a[4]),converter=H(a[5]);SignedDivide16State before=Parse(a,6),after=Parse(a,20);Memory m=new Memory();m.Load(before.DS,File.ReadAllBytes(prefix+"-before-ds.bin"));m.Load(before.SS,File.ReadAllBytes(prefix+"-before-ss.bin"));foreach(ushort s in new HashSet<ushort>(new ushort[]{first,second}))m.Load(s,File.ReadAllBytes(prefix+"-before-"+s.ToString("x4")+".bin"));Fpu fpu=new Fpu{CW=cw};bool returned=a.Length>34&&a[34]=="return";var actual=returned?BufferedPointCaller.ExecuteThroughReturn(m,fpu,before,converter):BufferedPointCaller.Execute(m,fpu,before,converter);if(actual.Outcome!=BufferedPointOutcome.Completed||actual.RetfExecuted!=returned||Show(actual.State)!=Show(after))throw new Exception("Caller context "+Show(actual.State)+" != "+Show(after));m.Compare(before.DS,File.ReadAllBytes(prefix+"-after-ds.bin"));m.Compare(before.SS,File.ReadAllBytes(prefix+"-after-ss.bin"));foreach(ushort s in new HashSet<ushort>(new ushort[]{first,second}))m.Compare(s,File.ReadAllBytes(prefix+"-after-"+s.ToString("x4")+".bin"));string one="LOAD32,WAIT,STORE_CW,WAIT,LOAD_CW,STORE_I64_POP,LOAD_CW";if(fpu.CW!=cw||fpu.Loads!=2||fpu.Pops!=2||fpu.Waits!=4||string.Join(",",fpu.Effects.ToArray())!=one+","+one)throw new Exception("FPU effect contract");Console.WriteLine("PASS original normal buffered-point caller "+a[1]+": all 13 word registers/full EFLAGS, 262144 DS/SS/buffer view bytes and FPU requests; RETF0C="+returned+". Full x87 status/faults and capacity callee remain outside projection.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
